# This file is used to generate the microservices, machines, graph and path for the social_network architecture
# The microservices are generated by calling the python files that generate the microservices
# The machines are generated by calling the corresponding file. There is a file for each network configuration
# The graph is generated by calling the graph.py file with the corresponding parameters (number of threads, cores and machines for each microservice)
# The path is generated by calling the path.py file

import subprocess
import argparse
import os

def parse_arguments():
    parser = argparse.ArgumentParser(description='Generate a service graph with input arguments')
    parser.add_argument('--end_seconds', type=int, default=60, help='Epoch end time in seconds')
    parser.add_argument('--monitor_interval', type=int, default=0, help='Interval at which the client will monitor the system (in seconds)')

    # 2026-11-19: replica support (post_storage + post_storage_mongodb) -
    # old --latency_1_3/--latency_3_4/--latency_3_5/--latency_5_6 renamed to
    # name the actual link rather than a fixed machine pair, since machine
    # ids downstream of post_storage now shift with instance count. NOT
    # forwarded to path.py (mirrors 4tier_multiple: instance counts only
    # affect machines.json/graph.json - path.json's structure is
    # instance-count-invariant, see path.py's 2026-11-19 notes).
    parser.add_argument('--postStorageInstances', type=int, default=1, help='Number of post_storage instances')
    parser.add_argument('--mongoInstances', type=int, default=1, help='Number of post_storage_mongodb instances')

    parser.add_argument("--latency_0_1", type=int, default=0, help="Latency between nginx and home_timeline")
    parser.add_argument("--latency_1_2", type=int, default=0, help="Latency between home_timeline and home_timeline_redis")
    parser.add_argument("--latency_ht_balancerPs", type=int, default=0, help="Latency between home_timeline and the post_storage load balancer")
    parser.add_argument("--latency_balancerPs_ps", type=int, default=0, help="Latency between the post_storage load balancer and each post_storage instance")
    parser.add_argument("--latency_ps_mmc", type=int, default=0, help="Latency between each post_storage instance and post_storage_memcached")
    parser.add_argument("--latency_ps_balancerMongo", type=int, default=0, help="Latency between each post_storage instance and the mongo load balancer")
    parser.add_argument("--latency_balancerMongo_mongo", type=int, default=0, help="Latency between the mongo load balancer and each post_storage_mongodb instance")
    parser.add_argument("--latency_mongo_mongoIo", type=int, default=0, help="Latency between each post_storage_mongodb instance and its mongo_io")
    parser.add_argument("--latency_cli", type=int, default=0, help="Latency between client and machine 0")

    parser.add_argument('--pPath0', type=int, default=80, help='Ratio (int 0-100) of memcached cache hit')
    parser.add_argument('--pPath1', type=int, default=15, help='Ratio (int 0-100) of memcached miss & mongodb hit')
    parser.add_argument('--pPath2', type=int, default=5, help='Ratio (int 0-100) of memcached miss & mongodb miss')

    parser.add_argument('--ngxThreads', type=int, default=8, help='Number of Nginx threads')
    parser.add_argument('--htThreads', type=int, default=8, help='Number of Home Timeline threads')
    parser.add_argument('--htRedisThreads', type=int, default=8, help='Number of Home Timeline Redis threads')
    parser.add_argument('--psThreads', type=int, default=8, help='Number of Post Storage threads')
    parser.add_argument('--mmcThreads', type=int, default=8, help='Number of Memcached threads')
    parser.add_argument('--mongoThreads', type=int, default=8, help='Number of MongoDB threads')
    parser.add_argument('--mongoIOThreads', type=int, default=8, help='Number of MongoDB IO threads')

    parser.add_argument('--ngxCores', type=int, default=4, help='Number of cores assigned to NGINX')
    parser.add_argument('--htCores', type=int, default=4, help='Number of cores assigned to Home Timeline')
    parser.add_argument('--htRedisCores', type=int, default=4, help='Number of cores assigned to Home Timeline Redis')
    parser.add_argument('--psCores', type=int, default=4, help='Number of cores assigned to Post Storage')
    parser.add_argument('--mmcCores', type=int, default=4, help='Number of cores assigned to Memcached')
    parser.add_argument('--mongoCores', type=int, default=4, help='Number of cores assigned to MongoDB')
    parser.add_argument('--mongoIOCores', type=int, default=4, help='Number of cores assigned to MongoDB IO')

    parser.add_argument('--machNxg', type=int, default=0, help='Machine ID where NGINX is deployed')
    parser.add_argument('--machHt', type=int, default=1, help='Machine ID where Home Timeline is deployed')
    parser.add_argument('--machHtRedis', type=int, default=2, help='Machine ID where Home Timeline Redis is deployed')
    parser.add_argument('--machMmc', type=int, default=3, help='Machine ID where Memcached is deployed')
    parser.add_argument('--machBalancerPs', type=int, default=4, help='Machine ID where the post_storage load balancer is deployed')
    args = parser.parse_args()
    return args

# Generate microservices
def generate_microservices():
    try:
        #Call net_stack.py
        proc = subprocess.run(['python3', 'net_stack.py'])
        if proc.returncode == 0:
            print("net_stack.py successfully executed")

        # Call nginx.py
        proc = subprocess.run(['python3', 'nginx.py'])
        if proc.returncode == 0:
            print("nginx.py successfully executed")

        # Call post_storage_memcached.py
        proc = subprocess.run(['python3', 'post_storage_memcached.py'])
        if proc.returncode == 0:
            print("post_storage_memcached.py successfully executed")

        # Call post_storage.py
        proc = subprocess.run(['python3', 'post_storage.py'])
        if proc.returncode == 0:
            print("post_storage.py successfully executed")

        # Call home_timeline.py
        proc = subprocess.run(['python3', 'home_timeline.py'])
        if proc.returncode == 0:
            print("home_timeline.py successfully executed")

        # Call home_timeline_redis.py
        proc = subprocess.run(['python3', 'home_timeline_redis.py'])
        if proc.returncode == 0:
            print("home_timeline_redis.py successfully executed")

        # Call post_storage_mongodb.py
        proc = subprocess.run(['python3', 'post_storage_mongodb.py'])
        if proc.returncode == 0:
            print("post_storage_mongodb.py successfully executed")

        # Call mongo_io.py
        proc = subprocess.run(['python3', 'mongo_io.py'])
        if proc.returncode == 0:
            print("mongo_io.py successfully executed")

        # Call load_balancer.py (2026-11-19: replica support - graph.py now
        # creates load_balancer_post_storage/load_balancer_mongo instances,
        # which need this model file; copied verbatim from 4tier_multiple,
        # which already uses the same generic load_balancer model)
        proc = subprocess.run(['python3', 'load_balancer.py'])
        if proc.returncode == 0:
            print("load_balancer.py successfully executed")

    except FileNotFoundError as e:
        print(e)

def generate_client(end_seconds, monitor_interval):
    try:
        # Call client.py
        proc = subprocess.run(['python3', 'client.py', f"--end_seconds={end_seconds}", f"--monitor_interval={monitor_interval}"])
        if proc.returncode == 0:
            print("client.py successfully executed")

    except FileNotFoundError as e:
        print(e)

def generate_machines(postStorageInstances, mongoInstances, latency_0_1, latency_1_2, latency_ht_balancerPs,
                       latency_balancerPs_ps, latency_ps_mmc, latency_ps_balancerMongo, latency_balancerMongo_mongo,
                       latency_mongo_mongoIo, latency_cli):
    try:
        # Call machines.py
        proc = subprocess.run(['python3', 'machines.py',
            f"--postStorageInstances={postStorageInstances}", f"--mongoInstances={mongoInstances}",
            f"--latency_0_1={latency_0_1}", f"--latency_1_2={latency_1_2}",
            f"--latency_ht_balancerPs={latency_ht_balancerPs}", f"--latency_balancerPs_ps={latency_balancerPs_ps}",
            f"--latency_ps_mmc={latency_ps_mmc}", f"--latency_ps_balancerMongo={latency_ps_balancerMongo}",
            f"--latency_balancerMongo_mongo={latency_balancerMongo_mongo}", f"--latency_mongo_mongoIo={latency_mongo_mongoIo}",
            f"--latency_cli={latency_cli}"])
        if proc.returncode == 0:
            print("machines.py successfully executed")

    except FileNotFoundError as e:
        print(e)

def generate_graph(ngxThreads, htThreads, htRedisThreads, psThreads, mmcThreads, mongoThreads, mongoIOThreads,
                    ngxCores, htCores, htRedisCores, psCores, mmcCores, mongoCores, mongoIOCores,
                    postStorageInstances, mongoInstances, machNxg, machHt, machHtRedis, machMmc, machBalancerPs):
    try:
        # Call graph.py
        proc = subprocess.run(['python3', 'graph.py',
            f"--ngxThreads={ngxThreads}", f"--htThreads={htThreads}", f"--htRedisThreads={htRedisThreads}",
            f"--psThreads={psThreads}", f"--mmcThreads={mmcThreads}", f"--mongoThreads={mongoThreads}",
            f"--mongoIOThreads={mongoIOThreads}", f"--ngxCores={ngxCores}", f"--htCores={htCores}",
            f"--htRedisCores={htRedisCores}", f"--psCores={psCores}", f"--mmcCores={mmcCores}",
            f"--mongoCores={mongoCores}", f"--mongoIOCores={mongoIOCores}",
            f"--postStorageInstances={postStorageInstances}", f"--mongoInstances={mongoInstances}",
            f"--machNxg={machNxg}", f"--machHt={machHt}", f"--machHtRedis={machHtRedis}",
            f"--machMmc={machMmc}", f"--machBalancerPs={machBalancerPs}"])
        if proc.returncode == 0:
            print("graph.py successfully executed")

    except FileNotFoundError as e:
        print(e)

def generate_path(pPath0, pPath1, pPath2):
    try:
        # Call path.py
        proc = subprocess.run(['python3', 'path.py', f"--pPath0={pPath0}", f"--pPath1={pPath1}", f"--pPath2={pPath2}"])
        if proc.returncode == 0:
            print("path.py successfully executed")

    except FileNotFoundError as e:
        print(e)

def main():
    os.makedirs("json/microservice", exist_ok=True)
    args = parse_arguments()
    generate_microservices()
    generate_client(args.end_seconds, args.monitor_interval)
    generate_machines(args.postStorageInstances, args.mongoInstances, args.latency_0_1, args.latency_1_2,
                       args.latency_ht_balancerPs, args.latency_balancerPs_ps, args.latency_ps_mmc,
                       args.latency_ps_balancerMongo, args.latency_balancerMongo_mongo, args.latency_mongo_mongoIo,
                       args.latency_cli)
    generate_graph(args.ngxThreads, args.htThreads, args.htRedisThreads, args.psThreads, args.mmcThreads,
                   args.mongoThreads, args.mongoIOThreads, args.ngxCores, args.htCores, args.htRedisCores,
                   args.psCores, args.mmcCores, args.mongoCores, args.mongoIOCores,
                   args.postStorageInstances, args.mongoInstances,
                   args.machNxg, args.machHt, args.machHtRedis, args.machMmc, args.machBalancerPs)
    generate_path(args.pPath0, args.pPath1, args.pPath2)

if __name__ == "__main__":
    main()
